 address=f'{a:08x}';rows=json.loads(subprocess.check_output(['ghidra','--project','bhunter-frame','disasm','0x'+address,'-n',str(count)],text=True));body=raw(a,size);assert b''.join(bytes.fromhex(r['bytes']) for r in rows)==body and rows[-1]['mnemonic']=='RET'
